-- ============================================================
-- SEMANTIC DRIFT ENGINE
-- BASELINE SCHEMA
--
-- Version: 000
--
-- This migration represents the complete application schema
-- after historical migrations 001, 002 and 003.
--
-- IMPORTANT:
-- - SQL only.
-- - No psql meta commands.
-- - No ownership statements.
-- - No GRANT / REVOKE statements.
-- - UUID values are generated by the application.
-- ============================================================


-- ============================================================
-- ENUM TYPES
-- ============================================================

CREATE TYPE user_role_enum AS ENUM (
    'admin',
    'user',
    'viewer'
);

CREATE TYPE page_type_enum AS ENUM (
    'pricing',
    'tos',
    'privacy',
    'sla',
    'docs'
);

CREATE TYPE crawl_freq_enum AS ENUM (
    'hourly',
    'daily',
    'weekly'
);


-- ============================================================
-- ORGANIZATIONS
-- ============================================================

CREATE TABLE organizations (
    id UUID PRIMARY KEY,

    name VARCHAR(255) NOT NULL,

    slug VARCHAR(100) NOT NULL,

    billing_email VARCHAR(255) NOT NULL,

    subscription_tier VARCHAR(50),

    quota_urls INTEGER,

    quota_requests INTEGER,

    is_active BOOLEAN,

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    updated_at TIMESTAMPTZ,

    CONSTRAINT organizations_slug_key
        UNIQUE (slug)
);


-- ============================================================
-- USERS
-- ============================================================

CREATE TABLE users (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    email VARCHAR(255) NOT NULL,

    password_hash VARCHAR(255),

    full_name VARCHAR(255) NOT NULL,

    role user_role_enum
        NOT NULL
        DEFAULT 'user',

    is_active BOOLEAN
        NOT NULL
        DEFAULT TRUE,

    email_verified BOOLEAN
        NOT NULL
        DEFAULT FALSE,

    verification_token VARCHAR(255),

    verification_token_expires TIMESTAMPTZ,

    verification_code_hash VARCHAR(64),

    verification_code_expires TIMESTAMPTZ,

    reset_token VARCHAR(255),

    reset_token_expires TIMESTAMPTZ,

    google_id VARCHAR(255),

    github_id VARCHAR(255),

    last_login TIMESTAMPTZ,

    login_attempts INTEGER
        NOT NULL
        DEFAULT 0,

    locked_until TIMESTAMPTZ,

    refresh_token VARCHAR(64),

    refresh_token_expires TIMESTAMPTZ,

    deleted_at TIMESTAMPTZ,

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    updated_at TIMESTAMPTZ,

    CONSTRAINT users_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE
);


-- ============================================================
-- USER SESSIONS
-- ============================================================

CREATE TABLE user_sessions (
    id UUID PRIMARY KEY,

    user_id UUID NOT NULL,

    refresh_token_hash VARCHAR(64) NOT NULL,

    expires_at TIMESTAMPTZ NOT NULL,

    created_at TIMESTAMPTZ
        NOT NULL
        DEFAULT NOW(),

    last_used_at TIMESTAMPTZ
        NOT NULL
        DEFAULT NOW(),

    revoked_at TIMESTAMPTZ,

    ip_address VARCHAR(64),

    user_agent VARCHAR(1024),

    is_revoked BOOLEAN
        NOT NULL
        DEFAULT FALSE,

    CONSTRAINT user_sessions_user_id_fkey
        FOREIGN KEY (user_id)
        REFERENCES users(id)
        ON DELETE CASCADE
);


-- ============================================================
-- CONSENT LOG
-- ============================================================

CREATE TABLE consent_logs (
    id UUID PRIMARY KEY,

    user_id UUID,

    consent_type VARCHAR(50) NOT NULL,

    granted BOOLEAN NOT NULL,

    policy_version VARCHAR(50) NOT NULL,

    ip_address VARCHAR(64),

    user_agent TEXT,

    metadata_json JSONB,

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    CONSTRAINT consent_logs_user_id_fkey
        FOREIGN KEY (user_id)
        REFERENCES users(id)
        ON DELETE CASCADE
);


-- ============================================================
-- ENTITIES
-- ============================================================

CREATE TABLE entities (
    id UUID PRIMARY KEY,

    domain VARCHAR(255) NOT NULL,

    name VARCHAR(255) NOT NULL,

    category VARCHAR(100),

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    updated_at TIMESTAMPTZ,

    organization_id UUID NOT NULL,

    CONSTRAINT entities_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE,

    CONSTRAINT uq_entities_organization_domain
        UNIQUE (
            organization_id,
            domain
        )
);


-- ============================================================
-- MONITORED PAGES
-- ============================================================

CREATE TABLE monitored_pages (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    entity_id UUID NOT NULL,

    url TEXT NOT NULL,

    page_type page_type_enum NOT NULL,

    crawl_frequency crawl_freq_enum,

    is_active BOOLEAN,

    custom_rules JSON,

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    updated_at TIMESTAMPTZ,

    CONSTRAINT monitored_pages_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE,

    CONSTRAINT monitored_pages_entity_id_fkey
        FOREIGN KEY (entity_id)
        REFERENCES entities(id)
        ON DELETE CASCADE
);


-- ============================================================
-- PAGE SNAPSHOTS
-- ============================================================

CREATE TABLE page_snapshots (
    id UUID PRIMARY KEY,

    monitored_page_id UUID NOT NULL,

    organization_id UUID NOT NULL,

    content_hash VARCHAR(64) NOT NULL,

    raw_content TEXT,

    content_size INTEGER,

    raw_content_path TEXT,

    crawled_at TIMESTAMPTZ
        DEFAULT NOW(),

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    CONSTRAINT page_snapshots_monitored_page_id_fkey
        FOREIGN KEY (monitored_page_id)
        REFERENCES monitored_pages(id)
        ON DELETE CASCADE,

    CONSTRAINT page_snapshots_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE
);


-- ============================================================
-- SEMANTIC DRIFT EVENTS
-- ============================================================

CREATE TABLE semantic_drift_events (
    id UUID PRIMARY KEY,

    monitored_page_id UUID NOT NULL,

    organization_id UUID NOT NULL,

    old_snapshot_id UUID NOT NULL,

    new_snapshot_id UUID NOT NULL,

    semantic_delta_json JSON NOT NULL,

    summary_text TEXT,

    analysis_status VARCHAR(20)
        NOT NULL
        DEFAULT 'pending',

    analysis_error TEXT,

    analysis_attempts INTEGER
        NOT NULL
        DEFAULT 0,

    analyzed_at TIMESTAMPTZ,

    risk_level VARCHAR(20)
        NOT NULL
        DEFAULT 'unknown',

    confidence DOUBLE PRECISION,

    impact_score INTEGER
        NOT NULL
        DEFAULT 0,

    category VARCHAR(50),

    change_type VARCHAR(50),

    changes_count INTEGER
        NOT NULL
        DEFAULT 0,

    chunk_count INTEGER
        NOT NULL
        DEFAULT 0,

    llm_tokens_used INTEGER
        NOT NULL
        DEFAULT 0,

    related_events JSON
        NOT NULL
        DEFAULT '[]'::json,

    entities_affected JSON
        NOT NULL
        DEFAULT '[]'::json,

    detected_at TIMESTAMPTZ
        NOT NULL
        DEFAULT NOW(),

    first_seen_at TIMESTAMPTZ
        NOT NULL
        DEFAULT NOW(),

    last_seen_at TIMESTAMPTZ,

    is_anomaly BOOLEAN
        NOT NULL
        DEFAULT FALSE,

    is_pattern_part BOOLEAN
        NOT NULL
        DEFAULT FALSE,

    is_reviewed BOOLEAN
        NOT NULL
        DEFAULT FALSE,

    is_archived BOOLEAN
        NOT NULL
        DEFAULT FALSE,

    CONSTRAINT semantic_drift_events_monitored_page_id_fkey
        FOREIGN KEY (monitored_page_id)
        REFERENCES monitored_pages(id)
        ON DELETE CASCADE,

    CONSTRAINT semantic_drift_events_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE,

    CONSTRAINT semantic_drift_events_old_snapshot_id_fkey
        FOREIGN KEY (old_snapshot_id)
        REFERENCES page_snapshots(id),

    CONSTRAINT semantic_drift_events_new_snapshot_id_fkey
        FOREIGN KEY (new_snapshot_id)
        REFERENCES page_snapshots(id),

    CONSTRAINT uq_semantic_drift_event_snapshot_pair
        UNIQUE (
            old_snapshot_id,
            new_snapshot_id
        ),

    CONSTRAINT ck_semantic_drift_event_analysis_status
        CHECK (
            analysis_status IN (
                'pending',
                'processing',
                'completed',
                'failed'
            )
        ),

    CONSTRAINT ck_semantic_drift_event_analysis_attempts
        CHECK (
            analysis_attempts >= 0
        )
);


-- ============================================================
-- PATTERNS
-- ============================================================

CREATE TABLE patterns (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    name VARCHAR(255) NOT NULL,

    description TEXT,

    pattern_type VARCHAR(50) NOT NULL,

    event_ids JSON,

    entities JSON,

    categories JSON,

    event_count INTEGER,

    entity_count INTEGER,

    time_span_days INTEGER,

    significance_score DOUBLE PRECISION,

    first_event_at TIMESTAMPTZ,

    last_event_at TIMESTAMPTZ,

    summary TEXT,

    detected_at TIMESTAMPTZ
        DEFAULT NOW(),

    is_active BOOLEAN,

    is_archived BOOLEAN,

    CONSTRAINT patterns_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE
);


-- ============================================================
-- ANOMALIES
-- ============================================================

CREATE TABLE anomalies (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    event_id UUID NOT NULL,

    anomaly_type VARCHAR(50) NOT NULL,

    description TEXT,

    expected_value DOUBLE PRECISION,

    actual_value DOUBLE PRECISION,

    deviation_score DOUBLE PRECISION,

    significance DOUBLE PRECISION,

    baseline_days INTEGER,

    detection_method VARCHAR(50),

    detected_at TIMESTAMPTZ
        DEFAULT NOW(),

    reviewed_at TIMESTAMPTZ,

    is_confirmed BOOLEAN,

    is_dismissed BOOLEAN,

    is_archived BOOLEAN,

    CONSTRAINT anomalies_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE,

    CONSTRAINT anomalies_event_id_fkey
        FOREIGN KEY (event_id)
        REFERENCES semantic_drift_events(id)
        ON DELETE CASCADE
);


-- ============================================================
-- ALERTS
-- ============================================================

CREATE TABLE alerts (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    event_id UUID NOT NULL,

    alert_type VARCHAR(50) NOT NULL,

    title VARCHAR(255) NOT NULL,

    message TEXT,

    severity VARCHAR(20),

    recommendation TEXT,

    affected_entities JSON,

    sent_at TIMESTAMPTZ,

    sent_to JSON,

    status VARCHAR(20),

    read_at TIMESTAMPTZ,

    dismissed_at TIMESTAMPTZ,

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    updated_at TIMESTAMPTZ,

    CONSTRAINT alerts_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE,

    CONSTRAINT alerts_event_id_fkey
        FOREIGN KEY (event_id)
        REFERENCES semantic_drift_events(id)
        ON DELETE CASCADE
);


-- ============================================================
-- WATCHLISTS
-- ============================================================

CREATE TABLE watchlists (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    name VARCHAR(255) NOT NULL,

    description TEXT,

    entity_ids JSON,

    page_ids JSON,

    categories JSON,

    alert_on_high_risk BOOLEAN,

    alert_on_medium_risk BOOLEAN,

    alert_on_pattern BOOLEAN,

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    updated_at TIMESTAMPTZ,

    last_checked_at TIMESTAMPTZ,

    is_active BOOLEAN,

    is_archived BOOLEAN,

    CONSTRAINT watchlists_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE
);


-- ============================================================
-- INVESTIGATIONS
-- ============================================================

CREATE TABLE investigations (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    name VARCHAR(255) NOT NULL,

    description TEXT,

    entity_ids JSON,

    event_ids JSON,

    date_range_start TIMESTAMPTZ,

    date_range_end TIMESTAMPTZ,

    categories JSON,

    findings TEXT,

    key_insights JSON,

    related_patterns JSON,

    status VARCHAR(20),

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    updated_at TIMESTAMPTZ,

    completed_at TIMESTAMPTZ,

    is_archived BOOLEAN,

    is_shared BOOLEAN,

    CONSTRAINT investigations_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE
);


-- ============================================================
-- API KEYS
-- ============================================================

CREATE TABLE api_keys (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    name VARCHAR(255) NOT NULL,

    key_hash VARCHAR(255) NOT NULL,

    permissions JSON,

    last_used_at TIMESTAMPTZ,

    expires_at TIMESTAMPTZ,

    is_active BOOLEAN,

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    CONSTRAINT api_keys_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE
);


-- ============================================================
-- WEBHOOK SUBSCRIPTIONS
-- ============================================================

CREATE TABLE webhook_subscriptions (
    id UUID PRIMARY KEY,

    organization_id UUID NOT NULL,

    url TEXT NOT NULL,

    events VARCHAR(50)[],

    secret_key VARCHAR(255) NOT NULL,

    is_active BOOLEAN,

    created_at TIMESTAMPTZ
        DEFAULT NOW(),

    updated_at TIMESTAMPTZ,

    CONSTRAINT webhook_subscriptions_organization_id_fkey
        FOREIGN KEY (organization_id)
        REFERENCES organizations(id)
        ON DELETE CASCADE
);


